      "vietnamese": "Tháng trước anh Tanaka chuyển nhà. Anh Miller đã giúp vận chuyển đồ đạc cho anh Tanaka. Chị Maria cũng giúp. Anh Tanaka nhờ anh Miller lắp giá kệ. Anh Yamada cho mượn xe. Nhờ mọi người giúp đỡ, anh Tanaka rất biết ơn.",
