          "q": "Hôm nay bạn đã kỳ vọng điều gì đó rất nhiều — một món ăn, cuộc hẹn, kết quả công việc — nhưng thực tế lại khiến bạn thất vọng hoặc tức giận. Hãy viết nhật ký kể lại chuyện đó, dùng「のに」để diễn đạt nỗi bất như ý của mình, và nêu lý do bằng「から」nhé!",
