          "q": "Sắp tới bạn có kế hoạch thi một chứng chỉ, học một kỹ năng mới, hay thay đổi một thói quen? Vì lý do gì bạn muốn làm vậy? Hãy viết về quyết định và mục tiêu của bạn.",
