          "ex": "最近[さいきん]、毎朝[まいあさ]30分[ぷん]走[はし]ることができるようになりました。走[はし]り終[お]わったとき、体[からだ]がすっきりして、一日[いちにち]の気分[きぶん]がとてもよくなります。"
